SELECT s1."c0" AS "x" FROM (SELECT s2."c0" AS "c0", s2."o" AS "o" FROM (SELECT s3."c2" AS "c0", s3."o" AS "o" FROM (SELECT s4."c0" AS "c0", s4."c1" AS "c1", s4."c1" AS "c2", s4."o" AS "o" FROM (SELECT s5."c0" AS "c0", s5."c1" AS "c1", s5."o" AS "o" FROM (SELECT v."c0" AS "c0", v."c1" AS "c1", v."o" AS "o" FROM (VALUES (1, 10, 0), (1, 30, 1), (2, 20, 2), (CAST(NULL AS NUMBER(38,0)), 40, 3), (2, CAST(NULL AS NUMBER(38,0)), 4), (1, 5, 5)) AS v("c0", "c1", "o")) AS s5 WHERE COALESCE((NOT (s5."c0" IS NULL)), FALSE)) AS s4) AS s3) AS s2 ORDER BY s2."o" ASC NULLS LAST LIMIT 2 OFFSET 1) AS s1 ORDER BY s1."o" ASC NULLS LAST
